"""Half-open integer interval utilities.

An interval is a pair (start, end) meaning the half-open range [start, end).
Pairs with start >= end are empty and are ignored everywhere.
"""

from __future__ import annotations


def _clean(intervals):
    """Yield non-empty (start, end) tuples from the input pairs."""
    for start, end in intervals:
        if start < end:
            yield (start, end)


def merge(intervals):
    """Merge overlapping and touching intervals; return sorted list of tuples."""
    result = []
    for start, end in sorted(_clean(intervals)):
        if result and start <= result[-1][1]:
            # Overlapping or touching: extend the current interval.
            if end > result[-1][1]:
                result[-1] = (result[-1][0], end)
        else:
            result.append((start, end))
    return result


def free_gaps(intervals, window):
    """Maximal sub-ranges of [ws, we) not covered by any interval, in order."""
    ws, we = window
    if ws >= we:
        return []
    clipped = []
    for start, end in sorted(_clean(intervals)):
        if end <= ws or start >= we:
            continue
        s = max(start, ws)
        e = min(end, we)
        if s < e:
            clipped.append((s, e))
    gaps = []
    cursor = ws
    for start, end in merge(clipped):
        if start > cursor:
            gaps.append((cursor, start))
        cursor = max(cursor, end)
    if cursor < we:
        gaps.append((cursor, we))
    return gaps


def max_overlap(intervals):
    """Largest number of non-empty intervals covering one common point."""
    starts = []
    ends = []
    for start, end in _clean(intervals):
        starts.append(start)
        ends.append(end)
    if not starts:
        return 0
    # Sweep line with binary search: at each unique start, all intervals with
    # start < that point are already open iff their end > that point (half-open).
    starts.sort()
    ends.sort()
    best = 0
    i = 0
    n = len(starts)
    while i < n:
        point = starts[i]
        # Count intervals covering `point`: start <= point < end.
        open_starts = _bisect_right(starts, point)
        open_ends = _bisect_left(ends, point)
        depth = open_starts - open_ends
        if depth > best:
            best = depth
        # Skip all identical start points.
        i += 1
        while i < n and starts[i] == point:
            i += 1
    return best


def _bisect_left(a, x):
    lo, hi = 0, len(a)
    while lo < hi:
        mid = (lo + hi) // 2
        if a[mid] < x:
            lo = mid + 1
        else:
            hi = mid
    return lo


def _bisect_right(a, x):
    lo, hi = 0, len(a)
    while lo < hi:
        mid = (lo + hi) // 2
        if a[mid] <= x:
            lo = mid + 1
        else:
            hi = mid
    return lo

"""LRU cache with per-entry time-to-live."""

import time
from collections import OrderedDict


class TTLCache:
    """An LRU cache in which each entry may carry its own time-to-live.

    Expiry rule: an entry stored at time ``t`` with lifetime ``ttl`` is
    expired when ``clock() >= t + ttl``; entries with ``ttl=None`` never
    expire.
    """

    def __init__(self, capacity, clock=time.monotonic):
        if capacity is None or capacity < 1:
            raise ValueError("capacity must be >= 1")
        if not callable(clock):
            raise TypeError("clock must be a zero-argument callable")
        self._capacity = capacity
        self._clock = clock
        # key -> (value, deadline); deadline is None for never-expiring entries.
        # OrderedDict iteration order goes from least to most recently used.
        self._data = OrderedDict()

    # ------------------------------------------------------------------ #
    # internal helpers
    # ------------------------------------------------------------------ #

    def _deadline(self, ttl, now):
        return None if ttl is None else now + ttl

    def _is_expired(self, deadline, now):
        return deadline is not None and now >= deadline

    def _purge_expired(self):
        """Remove every expired entry; return how many were removed."""
        now = self._clock()
        expired = [
            key
            for key, (_, deadline) in self._data.items()
            if self._is_expired(deadline, now)
        ]
        for key in expired:
            del self._data[key]
        return len(expired)

    # ------------------------------------------------------------------ #
    # public API
    # ------------------------------------------------------------------ #

    def put(self, key, value, ttl=None):
        if ttl is not None and ttl <= 0:
            raise ValueError("ttl must be > 0")
        now = self._clock()
        deadline = self._deadline(ttl, now)

        if key in self._data:
            # Replace value, restart lifetime, mark most recently used.
            self._data[key] = (value, deadline)
            self._data.move_to_end(key)
            return

        if len(self._data) >= self._capacity:
            # A new key would exceed capacity: drop expired entries first,
            # then fall back to evicting the least recently used one.
            self._purge_expired()
            if len(self._data) >= self._capacity:
                self._data.popitem(last=False)
        self._data[key] = (value, deadline)

    def get(self, key, default=None):
        entry = self._data.get(key)
        if entry is None:
            return default
        value, deadline = entry
        if self._is_expired(deadline, self._clock()):
            del self._data[key]
            return default
        self._data.move_to_end(key)
        return value

    def keys(self):
        self._purge_expired()
        return list(self._data.keys())

    def evict_expired(self):
        return self._purge_expired()

    def __contains__(self, key):
        entry = self._data.get(key)
        if entry is None:
            return False
        _, deadline = entry
        # Must not change recency.
        return not self._is_expired(deadline, self._clock())

    def __len__(self):
        self._purge_expired()
        return len(self._data)

"""Arithmetic expression evaluator: tokenizer + recursive-descent parser.

Grammar (lowest to highest precedence):
    expr   := term (('+' | '-') term)*
    term   := unary (('*' | '/' | '//' | '%') unary)*
    unary  := ('+' | '-') unary | power
    power  := atom ('**' unary)?          # right-associative; unary binds looser
    atom   := NUMBER | '(' expr ')' | call
    call   := 'min' '(' args ')' | 'max' '(' args ')' | 'abs' '(' expr ')'
"""

_DIGITS = set("0123456789")
_SINGLE_OPS = set("+-*/%()")


def _tokenize(text):
    tokens = []
    i = 0
    n = len(text)
    while i < n:
        c = text[i]
        if c.isspace():
            i += 1
        elif c in _DIGITS or c == ".":
            j = i
            seen_dot = False
            while j < n:
                ch = text[j]
                if ch in _DIGITS:
                    j += 1
                elif ch == "." and not seen_dot:
                    seen_dot = True
                    j += 1
                else:
                    break
            literal = text[i:j]
            tokens.append(("num", float(literal) if seen_dot else int(literal)))
            i = j
        elif c.isalpha() or c == "_":
            j = i
            while j < n and (text[j].isalnum() or text[j] == "_"):
                j += 1
            tokens.append(("name", text[i:j]))
            i = j
        elif text[i:i + 2] == "**":
            tokens.append(("**", "**"))
            i += 2
        elif text[i:i + 2] == "//":
            tokens.append(("//", "//"))
            i += 2
        elif c in _SINGLE_OPS:
            tokens.append((c, c))
            i += 1
        else:
            raise ValueError("unknown character %r" % c)
    return tokens


class _Parser:
    def __init__(self, tokens):
        self.tokens = tokens
        self.pos = 0

    def peek(self):
        if self.pos < len(self.tokens):
            return self.tokens[self.pos]
        return (None, None)

    def advance(self):
        tok = self.peek()
        self.pos += 1
        return tok

    def expect(self, kind):
        tok = self.advance()
        if tok[0] != kind:
            raise ValueError("expected %r, got %r" % (kind, tok[0]))
        return tok

    def parse(self):
        value = self.parse_expr()
        if self.pos != len(self.tokens):
            raise ValueError("unexpected token %r" % (self.tokens[self.pos][0],))
        return value

    def parse_expr(self):
        value = self.parse_term()
        while True:
            kind, _ = self.peek()
            if kind == "+":
                self.advance()
                value = value + self.parse_term()
            elif kind == "-":
                self.advance()
                value = value - self.parse_term()
            else:
                return value

    def parse_term(self):
        value = self.parse_unary()
        while True:
            kind, _ = self.peek()
            if kind not in ("*", "/", "//", "%"):
                return value
            self.advance()
            rhs = self.parse_unary()
            if kind == "*":
                value = value * rhs
            elif kind == "/":
                value = value / rhs
            elif kind == "//":
                value = value // rhs
            else:
                value = value % rhs

    def parse_unary(self):
        kind, _ = self.peek()
        if kind == "+":
            self.advance()
            return +self.parse_unary()
        if kind == "-":
            self.advance()
            return -self.parse_unary()
        return self.parse_power()

    def parse_power(self):
        base = self.parse_atom()
        if self.peek()[0] == "**":
            self.advance()
            return base ** self.parse_unary()
        return base

    def parse_args(self):
        args = []
        if self.peek()[0] != ")":
            args.append(self.parse_expr())
            while self.peek()[0] == ",":
                self.advance()
                args.append(self.parse_expr())
        self.expect(")")
        return args

    def parse_atom(self):
        kind, value = self.peek()
        if kind == "num":
            self.advance()
            return value
        if kind == "(":
            self.advance()
            inner = self.parse_expr()
            self.expect(")")
            return inner
        if kind == "name":
            self.advance()
            if value not in ("min", "max", "abs"):
                raise ValueError("unknown name %r" % value)
            args = self.parse_args()
            if value in ("min", "max"):
                if not args:
                    raise ValueError("%s() needs at least one argument" % value)
                return builtins_func(value, *args)
            if len(args) != 1:
                raise ValueError("abs() needs exactly one argument")
            return abs(args[0])
        if kind is None:
            raise ValueError("unexpected end of expression")
        raise ValueError("unexpected token %r" % kind)


def builtins_func(name, *args):
    return min(*args) if name == "min" else max(*args)


def evaluate(text):
    if not isinstance(text, str):
        raise ValueError("input must be a string")
    return _Parser(_tokenize(text)).parse()

